// Original touch input: one coordinate system, a fresh visible rect per move.
export function joystickVector(clientX,clientY,rect,deadzone=.12){const radius=Math.max(1,Math.min(rect.width,rect.height)*.35),dx=clientX-(rect.left+rect.width/2),dy=clientY-(rect.top+rect.height/2),length=Math.hypot(dx,dy),ratio=Math.min(1,length/radius);if(ratio<deadzone)return{x:0,z:0,dx:0,dy:0};return{x:dx/length*ratio,z:dy/length*ratio,dx:dx/Math.max(1,length/radius),dy:dy/Math.max(1,length/radius)};}
export class VirtualJoystick{
 constructor(zone,onChange){this.zone=zone;this.onChange=onChange;this.pointer=null;this.axes={x:0,z:0};zone.insertAdjacentHTML('beforeend','<div class="stick-base"></div><div class="stick-thumb"></div>');this.thumb=zone.querySelector('.stick-thumb');const move=(id,x,y)=>{if(id!==this.pointer)return;const a=joystickVector(x,y,zone.getBoundingClientRect());this.axes={x:a.x,z:a.z};this.thumb.style.transform=`translate(-50%,-50%) translate(${a.dx}px,${a.dy}px)`;onChange(this.axes);};
 if(window.PointerEvent){zone.addEventListener('pointerdown',e=>{if(this.pointer!==null)return;e.preventDefault();this.pointer=e.pointerId;try{zone.setPointerCapture(e.pointerId);}catch{}move(e.pointerId,e.clientX,e.clientY);},{passive:false});window.addEventListener('pointermove',e=>{if(e.pointerId===this.pointer){e.preventDefault();move(e.pointerId,e.clientX,e.clientY);}},{passive:false});for(const type of ['pointerup','pointercancel','lostpointercapture'])window.addEventListener(type,e=>{if(e.pointerId===this.pointer)this.reset();});}
 else{zone.addEventListener('touchstart',e=>{if(this.pointer!==null)return;const t=e.changedTouches[0];e.preventDefault();this.pointer=t.identifier;move(t.identifier,t.clientX,t.clientY);},{passive:false});window.addEventListener('touchmove',e=>{const t=[...e.touches].find(t=>t.identifier===this.pointer);if(t){e.preventDefault();move(t.identifier,t.clientX,t.clientY);}},{passive:false});for(const type of ['touchend','touchcancel'])window.addEventListener(type,e=>{if([...e.changedTouches].some(t=>t.identifier===this.pointer))this.reset();});}
 for(const type of ['blur','orientationchange','resize'])window.addEventListener(type,()=>this.reset());document.addEventListener('visibilitychange',()=>{if(document.hidden)this.reset();});}
 reset(){this.pointer=null;this.axes={x:0,z:0};this.thumb.style.transform='translate(-50%,-50%)';this.onChange(this.axes);}
}
